import java.math.BigDecimal;
import java.util.Objects;

public record Measurement(BigDecimal amount, String unit) {
    public Measurement {
        Objects.requireNonNull(amount);
        Objects.requireNonNull(unit);
    }
}

files.src/MeasurementCache.java:
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public final class MeasurementCache {
    private final Map<Measurement, String> results = new HashMap<>();
    public void remember(Measurement key, String result) { results.put(key, result); }
    public Optional<String> find(Measurement key) { return Optional.ofNullable(results.get(key)); }
    public int size() { return results.size(); }
}

files.src/ReportFormatter.java:
public final class ReportFormatter {
    public String render(Measurement reading) {
        return reading.amount().toPlainString() + " " + reading.unit();
    }
}

files.src/Demo.java:
import java.math.BigDecimal;

public final class Demo {
    public static void main(String[] args) {
        var first = new Measurement(new BigDecimal("2.0"), "kg");
        var second = new Measurement(new BigDecimal("2.00"), "kg");
        var cache = new MeasurementCache();
        cache.remember(first, "result-A");
        System.out.println("second lookup before insert = " + cache.find(second));
        cache.remember(second, "result-B");
        System.out.println("cache entries = " + cache.size());
        var reports = new ReportFormatter();
        System.out.println("first report = " + reports.render(first));
        System.out.println("second report = " + reports.render(second));
    }
}

